import{_ as t,o as a,c as n,ah as o}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Teacher","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/enseignant/index.md","filePath":"src/en/guide/enseignant/index.md"}'),s={name:"en/guide/enseignant/index.md"};function r(i,e,d,c,h,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="teacher" tabindex="-1">Teacher <a class="header-anchor" href="#teacher" aria-label="Permalink to &quot;Teacher&quot;">​</a></h1><p>As a teacher, you only see your own classes and subjects: the ones the administrator has explicitly assigned to you (on the administration side, <strong>School setup → Teacher assignments</strong>). If a class or subject doesn&#39;t appear in your dropdowns, no assignment links you to it yet — flag it to your administrator.</p><p>If you are designated <strong>homeroom teacher</strong> for a class, you also get a consolidated view of that class and its end-of-period general appreciations, described in the third page below.</p><p>This guide covers four activities:</p><table tabindex="0"><thead><tr><th>Page</th><th>What you do there</th></tr></thead><tbody><tr><td><a href="/era-guide/en/guide/enseignant/notes-et-evaluations.html">Grades and evaluations</a></td><td>Create an evaluation, enter grades, record competency observations</td></tr><tr><td><a href="/era-guide/en/guide/enseignant/bulletins-et-cahier-texte.html">Report cards and lesson log</a></td><td>Write report card appreciations, keep the lesson log</td></tr><tr><td><a href="/era-guide/en/guide/enseignant/registre-et-emploi-du-temps.html">Homeroom and schedule</a></td><td>View your homeroom class register (homeroom teacher) and your own schedule</td></tr><tr><td><a href="/era-guide/en/guide/enseignant/notes-superieur.html">Course element marks</a></td><td>Enter the marks of your course elements in a higher education institution</td></tr></tbody></table><h2 id="attendance-and-justifications" tabindex="-1">Attendance and justifications <a class="header-anchor" href="#attendance-and-justifications" aria-label="Permalink to &quot;Attendance and justifications&quot;">​</a></h2><p>You also take your classes&#39; attendance — from the <strong>Take attendance</strong> button on your dashboard, or <strong>School life → Attendance</strong> — and you can handle the absence justifications families send for your classes. Both are described in <a href="/era-guide/en/guide/vie-scolaire/presences-et-absences.html">Attendance and absences</a>, in the school life guide.</p><div class="info custom-block"><p class="custom-block-title">Parents are not told of every grade</p><p>Saving a grade sends nothing to families: they learn the period&#39;s results with the report card the administration publishes, and can check averages in their space meanwhile. An unjustified absence, on the other hand, notifies them as soon as the attendance is saved.</p></div><p>For anything about your personal account (login, profile, security, notifications), common to every role, see <a href="/era-guide/en/guide/prise-en-main.html">Getting started</a>.</p>',9)])])}const p=t(s,[["render",r]]);export{g as __pageData,p as default};
